/** Escapes text for HTML content and attribute values. */
export const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

/** A base class plus the caller's extra classes. */
export const cls = (base, extra) => (extra ? `${base} ${esc(extra)}` : base);

/** ` name="value"`, ` name` for true, nothing for null, undefined or false. */
export const attr = (name, value) => (value == null || value === false ? '' : value === true ? ` ${name}` : ` ${name}="${esc(value)}"`);

/** Several attributes from an object, in order. */
export const attrs = (obj) => Object.entries(obj || {}).map(([k, v]) => attr(k, v)).join('');

/** An id that's stable for the same seed, for linking labels, hints and panels. */
export function uid(prefix, seed) {
  let h = 0;
  for (const ch of String(seed ?? '')) h = (h * 31 + ch.charCodeAt(0)) | 0;
  return `${prefix}-${(h >>> 0).toString(36)}`;
}

